    def related_objects(self, related, objs):
        """
        Get a QuerySet of objects related to `objs` via the relation `related`.
        Only the primary key and the foreign‑key field used for the relation
        are selected, avoiding fetching unnecessary columns.
        """
        qs = related.related_model._base_manager.using(self.using).filter(
            **{"%s__in" % related.field.name: objs}
        )
        # Ensure the query only pulls the PK and the FK column required for
        # the relation.
        pk_name = related.related_model._meta.pk.name
        fk_name = related.field.name
        # ``only`` accepts field names; if the FK is the PK we avoid duplication.
        if pk_name == fk_name:
            return qs.only(pk_name)
        return qs.only(pk_name, fk_name)
