    def iterator(self):
        """
        Return an iterator over the results of the QuerySet.

        The iterator class depends on the type of query being executed.
        When a QuerySet is created from a pickled ``Query`` that was built
        using ``values()`` or ``values_list()``, the stored ``_iterable_class``
        may still point to the default ``ModelIterable``.  In such cases we
        need to choose the appropriate iterable dynamically based on the
        ``Query`` characteristics.
        """
        if self._result_cache is not None:
            return iter(self._result_cache)

        # Determine the correct iterable class for the current query.
        if self.query.is_values_query():
            iterable_class = ValuesIterable
        elif self.query.is_values_list_query():
            # ``ValuesListIterable`` is defined later in this module.
            iterable_class = ValuesListIterable
        else:
            iterable_class = self._iterable_class

        return iterable_class(self)
