    def clean(self, value):
        """
        Return a list of values from each field, after validation.
        """
        # If the overall field is required, ensure that at least one subfield
        # has data.
        if self.required and not any(value):
            raise ValidationError(self.error_messages['required'], code='required')
        value = value or []
        cleaned_data = []
        errors = []
        for i, field in enumerate(self.fields):
            # Determine the value for this subfield.
            field_value = value[i] if i < len(value) else ''
            # Validate the subfield regardless of `require_all_fields`.
            try:
                cleaned_data.append(field.clean(field_value))
            except ValidationError as e:
                errors.append(e)
