    def __or__(self, other):
        """
        Combine this Q object with ``other`` using the OR connector.
        If ``other`` is a Q instance the original logic is used.
        If ``other`` is an expression (e.g. Exists) we build a new Q that
        contains both this Q and the expression as children.
        """
        if isinstance(other, Q):
            return self._combine(other, self.OR)

        # ``other`` is not a Q (e.g., an Exists expression). Treat it as a
        # raw condition child.
        if not self:
            # An empty Q combined with an expression is just that expression.
            return Q(other, _connector=self.OR)
        obj = type(self)()
        obj.connector = self.OR
        obj.add(self, self.OR)
        obj.add(other, self.OR)
        return obj

    def __and__(self, other):
        """
        Combine this Q object with ``other`` using the AND connector.
        If ``other`` is a Q instance the original logic is used.
        If ``other`` is an expression (e.g. Exists) we build a new Q that
        contains both this Q and the expression as children.
        """
        if isinstance(other, Q):
            return self._combine(other, self.AND)

        # ``other`` is not a Q (e.g., an Exists expression). Treat it as a
        # raw condition child.
        if not self:
            # An empty Q combined with an expression is just that expression.
            return Q(other, _connector=self.AND)
        obj = type(self)()
        obj.connector = self.AND
        obj.add(self, self.AND)
        obj.add(other, self.AND)
        return obj
