    # to be imported during collection.
    if path.basename == "__init__.py":
        # Look for test files in the same directory.
        test_file_patterns = parent.config.getini("python_files")
        for child in path.dirpath().listdir():
            if child.check(file=1) and path_matches_patterns(child, test_file_patterns):
