def pytest_pycollect_makemodule(path, parent):
    if path.basename == "__init__.py":
        # In earlier pytest versions __init__.py files that did not contain
        # any test modules were ignored.  The regression in 5.2.3 caused such
        # files to be collected as packages, leading to import errors.
        # Skip treating the file as a package unless the directory contains
        # at least one module that matches the test file patterns.
        dirpath = path.dirpath()
        has_test_module = any(
            p.check(file=1)
            and path_matches_patterns(p, parent.config.getini("python_files"))
            for p in dirpath.listdir()
        )
        if not has_test_module:
            return None
        return Package(path, parent)
