def pytest_pycollect_makemodule(path, parent):
    """
    Create a module collector for *path*.

    ``__init__.py`` files are only turned into a ``Package`` collector when the
    containing directory actually holds test files (according to the
    ``python_files`` ini option).  This restores the pre‑5.2.3 behaviour where
    stray ``__init__.py`` files are ignored instead of being imported eagerly.
    """
    if path.basename == "__init__.py":
        # Look for any test file in the same directory.
        test_patterns = parent.config.getini("python_files")
        for child in path.dirpath().listdir():
            if child.check(file=1) and path_matches_patterns(child, test_patterns):
                return Package(path, parent)
        # No test files – do not collect this ``__init__.py``.
        return None
    return Module(path, parent)
