    def _eval_is_zero(self):
        """
        Determine if an Add expression is identically zero.

        The previous implementation could incorrectly return ``False`` for
        expressions that are zero but whose terms are not recognized as
        purely real or purely imaginary (e.g. ``-2*I + (1 + I)**2``).  The
        logic below augments the original approach by inspecting the real
        and imaginary parts of each term when their ``is_real`` or
        ``is_imaginary`` attributes are inconclusive.
        """
