        z = 0            # count of zero real terms
        im = False       # at least one term known to be purely imaginary
        im_or_z = False  # at least one term known to be I*real (real after multiplying by I)

        for a in self.args:
            # Quick checks based on .is_real / .is_imaginary
            if a.is_real:
                if a.is_zero:
                    z += 1
                elif a.is_zero is False:
                    nz.append(a)
                else:
                    return
                continue

            if a.is_imaginary:
                im = True
                continue

            # If (I*a) is known to be real, treat as real after multiplication by I
            if (S.ImaginaryUnit * a).is_real:
                im_or_z = True
                continue

            # If the above are inconclusive, fall back to inspecting the
            # real and imaginary parts of the term.
            re_a, im_a = a.as_real_imag()
            # If the term is known to be purely real (imag part zero)
            if im_a.is_zero:
