                    z += 1
                elif re_a.is_zero is False:
                    nz.append(re_a)
                else:
                    return
                continue

            # If the term is known to be purely imaginary (real part zero)
            if re_a.is_zero:
                im = True
                continue

            # If multiplying by I makes it real, treat it as such
            if (S.ImaginaryUnit * a).is_real:
                im_or_z = True
                continue

            # Otherwise we cannot decide
            return

