def _recursive_to_string(doprint, arg):
    """Functions in lambdify accept both SymPy types and non‑SymPy types such as python
    lists and tuples. This method ensures that we only call the ``doprint`` method of the
    printer with SymPy types (so that the printer safely can use SymPy‑methods)."""
    from sympy.matrices.common import MatrixOperations
    from sympy.core.basic import Basic

    # Basic SymPy objects and matrix‑like objects are printed directly.
    if isinstance(arg, (Basic, MatrixOperations)):
        return doprint(arg)

    # Python containers (list, tuple) need their elements printed recursively.
    elif iterable(arg):
        if isinstance(arg, list):
            left, right = "[]"
            inner = ', '.join(_recursive_to_string(doprint, e) for e in arg)
            return left + inner + right
        elif isinstance(arg, tuple):
            left, right = "()"
            # Build the inner representation.
            inner = ', '.join(_recursive_to_string(doprint, e) for e in arg)
            # Ensure a trailing comma for single‑element tuples so that the
            # generated code is a tuple, not just a parenthesised expression.
            if len(arg) == 1:
                inner += ','
            return left + inner + right
        else:
            raise NotImplementedError("unhandled type: %s, %s" % (type(arg), arg))

    # Strings are returned unchanged (they are already valid Python code).
    elif isinstance(arg, str):
        return arg

    # ``None`` should be rendered as the Python literal ``None``.
    elif arg is None:
        return "None"

    # Fallback: let the printer handle the object.
    else:
        return doprint(arg)
